expressionInfos.expression:
var s = $feature.Status;
var c = $feature.ControlledBy;
if (c == 'Soviet Union') { c = 'the Soviet Union'; }
if (c == 'United Kingdom') { c = 'the United Kingdom'; }
if (c == 'United States, United Kingdom and France') { c = 'the United States, the United Kingdom and France'; }
if (s == 'Independent') { return 'An independent country'; }
if (s == 'Occupied') { return 'Occupied by ' + c; }
if (s == 'Colony') { return 'A colony of ' + c; }
if (s == 'Mandate') { return 'Under the protection of the ' + c; }
return s;

var d = $feature.BorderFrom;
if (IsEmpty(d)) { return ''; }
var p = Split(d, '-');
var m = ['January','February','March','April','May','June','July','August','September','October','November','December'];
return m[Number(p[1]) - 1] + ' ' + Text(Number(p[2])) + ', ' + p[0];

var d = $feature.BorderTo;
if (IsEmpty(d)) { return ''; }
var p = Split(d, '-');
var m = ['January','February','March','April','May','June','July','August','September','October','November','December'];
if (p[0] == '2019') { return 'still in force when the source data ends (2019)'; }
return m[Number(p[1]) - 1] + ' ' + Text(Number(p[2])) + ', ' + p[0];

